<?php
// The gallery holds the source address; this self-contained page uses relative URLs.
if (isset($_GET['source'])) {
    $gallery = file_get_contents(__DIR__ . '/index.php');
    if (preg_match('~<li>\\s*<div class="entry-title"><a href="hestra-staple-works.php".*?</li>~s', $gallery, $entry)
        && preg_match('~Inspired by Jon\\x27s <a href="([^"]+)"~', $entry[0], $link)) {
        $url = html_entity_decode($link[1], ENT_QUOTES, 'UTF-8');
        if (parse_url($url, PHP_URL_SCHEME) === 'https') { header('Location: ' . $url, true, 302); exit; }
    }
    http_response_code(404); exit('Source not found.');
}
?><!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hestra Staple Works</title>
<style>
:root{--paper:#f4e9cc;--ink:#202a26;--red:#b93320;--green:#355747;--yellow:#e4ba47}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Palatino Linotype","Book Antiqua",Palatino,serif}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.12;background:repeating-linear-gradient(0deg,transparent 0 3px,#9c855c 4px);z-index:9}button,input{font:inherit}button{cursor:pointer;touch-action:manipulation}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid var(--red);outline-offset:4px}a{color:inherit}header{max-width:1180px;margin:auto;display:flex;justify-content:space-between;padding:24px 22px;border-bottom:1px solid #202a2640;font-family:"Courier New",monospace;font-size:12px;text-transform:uppercase;letter-spacing:1px}main{max-width:1180px;margin:auto;padding:30px 22px}.hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:20px}.eyebrow{font-family:"Courier New",monospace;letter-spacing:2px;font-size:12px;text-transform:uppercase;color:var(--red)}h1{font-size:clamp(55px,8vw,102px);letter-spacing:-5px;line-height:.9;margin:18px 0 22px;font-weight:900}h1 em{font-weight:normal;color:var(--red)}.lede{font-size:19px;line-height:1.5;max-width:440px}.catalogue{margin:0;transform:rotate(-3deg);border:2px solid var(--ink);background:#ebd68f;box-shadow:8px 8px 0 #202a26}.catalogue img{display:block;width:100%;aspect-ratio:3/2;object-fit:cover}.catalogue figcaption{padding:10px 15px;font-family:"Courier New",monospace;font-size:11px;border-top:2px solid var(--ink);display:flex;justify-content:space-between}.workshop{margin-top:42px;display:grid;grid-template-columns:1.1fr 1fr;border:2px solid var(--ink)}.bench{padding:26px;background:#e0bb5f;border-right:2px solid var(--ink)}.ticket{background:#fff9e9;padding:20px;box-shadow:3px 3px 0 #202a2630;border-top:6px solid var(--red)}.ticket h2{font-size:28px;margin:10px 0}.small{font:12px/1.6 "Courier New",monospace}.ticket p{line-height:1.5;margin-bottom:0}.paper-area{height:210px;position:relative;display:flex;justify-content:center;align-items:center;overflow:hidden;margin-top:16px}.sheet{width:220px;height:142px;background:#fffdf0;transform:translateX(var(--offset,0px)) rotate(-5deg);box-shadow:2px 4px 0 #dcd6bd,4px 8px 0 #fffdf0,6px 12px 0 #dcd6bd,8px 16px 0 #fffdf0;position:relative;border:1px solid #9c956d;transition:transform .15s}.sheet:after{content:"";position:absolute;top:35px;left:25px;right:25px;height:60px;background:repeating-linear-gradient(transparent 0 11px,#a7af9a 12px 13px)}.target{position:absolute;left:14px;top:12px;width:24px;height:13px;border:2px dashed var(--red);z-index:2}.staple{position:absolute;width:25px;height:8px;left:calc(50% - 97px);top:48px;border:3px solid #525d59;border-bottom:0;z-index:4;opacity:0}.staple.done{opacity:1}.crosshair{position:absolute;left:calc(50% - 108px);top:36px;width:46px;height:36px;border:1px solid #202a2660;border-radius:50%;pointer-events:none}.seal{display:flex;gap:8px;flex-wrap:wrap}.seal span{width:38px;height:38px;border:1px dashed #202a2680;border-radius:50%;display:grid;place-items:center;font:bold 14px "Courier New",monospace}.seal .finished{border:2px solid var(--red);color:var(--red);transform:rotate(-12deg);background:#fff9e970}.controls{padding:26px;background:#f8f0da}fieldset{padding:0;border:0;margin:0 0 22px}legend,.label{font:bold 12px "Courier New",monospace;letter-spacing:1px;margin-bottom:12px;display:block;text-transform:uppercase}.cartridges{display:flex;gap:10px}.cartridge{flex:1;text-align:left;background:transparent;color:var(--ink);border:2px solid var(--ink);padding:12px}.cartridge strong{font-size:27px;display:block}.cartridge[aria-pressed=true]{background:var(--ink);color:var(--paper);box-shadow:3px 3px 0 var(--red)}input[type=range]{width:100%;accent-color:var(--red);margin:10px 0 5px;cursor:pointer}.ends{display:flex;justify-content:space-between;font:11px "Courier New",monospace}label.check{display:flex;gap:10px;align-items:center;font-size:15px;margin:18px 0}input[type=checkbox]{width:20px;height:20px;accent-color:var(--green)}.press{width:100%;background:var(--red);color:#fff8df;border:2px solid var(--ink);padding:17px;font:bold 19px "Courier New",monospace;box-shadow:0 5px 0 var(--ink)}.press:active{transform:translateY(4px);box-shadow:0 1px 0 var(--ink)}.press:disabled{opacity:.6;cursor:default}.next{background:var(--green);color:var(--paper);padding:12px 20px;border:2px solid var(--ink);margin-top:10px;width:100%}.message{min-height:65px;line-height:1.4;margin:18px 0 0}.note{margin-top:25px;display:grid;grid-template-columns:1fr 1fr;gap:28px;font-size:14px;line-height:1.6}.note h3{margin-bottom:4px}.foot{padding:25px 0;margin-top:22px;border-top:1px solid #202a2640;font-size:14px}.thunk{animation:thunk .25s}@keyframes thunk{40%{transform:translateY(6px)}}@media(max-width:700px){header{font-size:10px}.hero,.workshop,.note{grid-template-columns:1fr}h1{letter-spacing:-3px}.catalogue{margin:14px 8px 8px}.bench{border-right:0;border-bottom:2px solid var(--ink)}.controls,.bench{padding:20px}.hero{gap:0}.lede{font-size:17px}.workshop{margin-top:30px}}@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}
</style></head><body><header><a href="./">← Chloe reads Jon</a><span>Est. 1944 / a tiny workshop</span></header>
<main><section class="hero"><div><span class="eyebrow">Good tools. Small satisfactions.</span><h1>Hestra<br>Staple <em>Works.</em></h1><p class="lede">Six little paper jobs. One gloriously overbuilt stapler. Load the right legs, square the stack, and give it a good <em>thunk.</em></p></div><figure class="catalogue"><img src="data:image/webp;base64," alt="Original vintage catalogue illustration of a chrome and black stapler over a stack of paper"><figcaption><span>K2 / THE WORKHORSE</span><span>Hestra, Sweden</span></figcaption></figure></section>
<section class="workshop" aria-label="Interactive stapling workshop"><div class="bench"><article class="ticket"><span id="jobNumber" class="eyebrow"></span><h2 id="jobTitle"></h2><div class="small" id="jobSheets"></div><p id="jobDesc"></p></article><div class="paper-area" aria-label="Paper alignment preview"><div class="sheet" id="sheet"><span class="target"></span></div><div class="crosshair" aria-hidden="true"></div><span class="staple" id="staple"></span></div><div class="seal" id="seals" aria-label="Completed jobs"></div></div>
<div class="controls"><fieldset><legend>01 / Load the cartridge</legend><div class="cartridges"><button class="cartridge" aria-pressed="true" data-length="6"><strong>6 mm</strong><span class="small">Up to 20 sheets</span></button><button class="cartridge" aria-pressed="false" data-length="8"><strong>8 mm</strong><span class="small">Up to 50 sheets</span></button></div></fieldset>
<label class="label" for="alignment">02 / Square the paper</label><input type="range" id="alignment" min="-30" max="30" value="19"><div class="ends"><span>← Slide left</span><span>Match dashed corner to ring</span><span>Right →</span></div>
<label class="check"><input type="checkbox" id="split">Split into two equal-ish bundles</label>
<label class="label" for="force">03 / Set your press</label><input type="range" id="force" min="0" max="100" value="35"><div class="ends"><span>A gentle tap</span><output id="forceValue">35%</output><span>A heroic slam</span></div>
<p class="small" id="hint"></p><button class="press" id="press">THUNK ↓</button><p class="message" id="message" role="status" aria-live="polite">Your first job is on the bench. There’s no clock and no score.</p><button class="next" id="next" hidden>Next paper job →</button></div></section>
<section class="note"><div><h3>Leg length, not brute force.</h3>Jon’s 2008 post says this Swedish stapler handles 20 sheets with 6 mm staples, or 50 with 8 mm. Here, use the shortest cartridge that can comfortably handle your bundle.</div><div><h3>A toy, not a workshop manual.</h3>The press percentages and alignment tolerance are playful inventions, not manufacturer specifications. Sound is off until you enable it. <button id="sound" aria-pressed="false">Sound: off</button></div></section>
<footer class="foot">Inspired by Jon’s <a href="?source=1">The Perfect Stapler</a>. A small tribute to finding exactly the right tool.</footer></main>
<script>
const jobs=[
{title:'The neighbourhood newsletter',sheets:8,desc:'Eight pages of local news. A neighbour’s cat has apparently become deputy editor.'},
{title:'The detective dossier',sheets:20,desc:'The case of the disappearing biscuit. Twenty pages. Suspiciously thorough.'},
{title:'The Saturday comic',sheets:28,desc:'A robot, a cedar forest, and twenty-eight pages that need to stay together.'},
{title:'The grand piano score',sheets:50,desc:'Fifty pages. Right on the workhorse’s upper limit.'},
{title:'The one-page-too-many problem',sheets:51,desc:'A fifty-one-page car catalogue. A bigger slam won’t fix a capacity problem.'},
{title:'The family recipe book',sheets:16,desc:'Sixteen pages of meals worth making again. Last job before tea.'}
];
let job=0,length=6,complete=false,sound=false,ctx;
const el=id=>document.getElementById(id);
function bundles(){return el('split').checked?Math.ceil(jobs[job].sheets/2):jobs[job].sheets}
function update(){el('sheet').style.setProperty('--offset',el('alignment').value+'px');el('forceValue').value=el('force').value+'%';let n=bundles();el('hint').textContent='Workshop press target: '+Math.min(90,25+n)+'% (within 10%). '+(el('split').checked?'Two bundles: '+Math.ceil(jobs[job].sheets/2)+' + '+Math.floor(jobs[job].sheets/2)+' sheets.':'One bundle: '+n+' sheets.')}
function load(){complete=false;el('jobNumber').textContent='Job '+(job+1)+' / 06';el('jobTitle').textContent=jobs[job].title;el('jobSheets').textContent=jobs[job].sheets+' SHEETS / PAPER ORDER';el('jobDesc').textContent=jobs[job].desc;el('alignment').value=job%2===0?19:-17;el('split').checked=false;el('force').value=35;el('staple').classList.remove('done');el('press').disabled=false;el('next').hidden=true;update();renderSeals()}
function renderSeals(){el('seals').replaceChildren(...jobs.map((j,i)=>{let s=document.createElement('span');s.textContent=i<job||i===job&&complete?'✓':i+1;s.className=i<job||i===job&&complete?'finished':'';s.title=j.title;return s}))}
document.querySelectorAll('[data-length]').forEach(b=>b.addEventListener('click',()=>{length=Number(b.dataset.length);document.querySelectorAll('[data-length]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))}));
['alignment','force','split'].forEach(id=>el(id).addEventListener('input',update));
el('sound').onclick=()=>{sound=!sound;el('sound').textContent='Sound: '+(sound?'on':'off');el('sound').setAttribute('aria-pressed',String(sound));if(sound){const Audio=window.AudioContext||window.webkitAudioContext;if(Audio){ctx=ctx||new Audio();ctx.resume()}else{sound=false;el('sound').textContent='Sound unavailable';el('sound').setAttribute('aria-pressed','false')}}};
function thunk(){if(!sound||!ctx)return;const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(150,ctx.currentTime);o.frequency.exponentialRampToValueAtTime(35,ctx.currentTime+.12);g.gain.setValueAtTime(.18,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.16);o.connect(g).connect(ctx.destination);o.start();o.stop(ctx.currentTime+.17)}
el('press').onclick=()=>{if(complete)return;thunk();el('sheet').classList.remove('thunk');void el('sheet').offsetWidth;el('sheet').classList.add('thunk');let n=bundles(),feedback='';
if(n>50)feedback='Too thick! This job needs two bundles. No amount of enthusiasm will make 51 fit into 50.';
else if(length===6&&n>20)feedback='Those 6 mm legs are too short for '+n+' sheets. Load the 8 mm cartridge.';
else if(length===8&&n<=20)feedback='That will hold, but the workshop asks for the shortest suitable legs. Try 6 mm.';
else if(Math.abs(Number(el('alignment').value))>4)feedback='A crooked corner! Slide the paper until the dashed mark sits inside the ring.';
else if(Math.abs(Number(el('force').value)-Math.min(90,25+n))>10)feedback=Number(el('force').value)<Math.min(90,25+n)?'A little timid. Bring the press closer to the workshop target.':'A little overenthusiastic! Ease the press back toward the target.';
else{complete=true;el('staple').classList.add('done');el('press').disabled=true;renderSeals();feedback=el('split').checked?'Two tidy bundles, both fastened. Lovely work.':'A clean staple. That tiny satisfaction never gets old.';el('next').hidden=false;if(job===jobs.length-1){feedback='All six orders finished. Certified Keeper of the Satisfying Thunk. Tea is now entirely justified.';el('next').textContent='Open the workshop again ↻'}}
el('message').textContent=feedback};
el('next').onclick=()=>{job=(job+1)%jobs.length;el('next').textContent='Next paper job →';el('message').textContent='Fresh paper on the bench. Choose your cartridge, alignment, and press.';load()};
load();
</script></body></html>